function formatDateDDMMYYYY(date) {
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
}

const today = new Date();
const todayStr = formatDateDDMMYYYY(today);
const sevenDaysOut = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
const nextActionDateStr = formatDateDDMMYYYY(sevenDaysOut);

const output = [];

for (const item of $input.all()) {
  const row = item.json;

  const status = (row['Status'] || '').toString().trim().toLowerCase();
  const nextActionDate = (row['Next Action Date'] || '').toString().trim();
  const email = (row['Email'] || '').toString().trim();
  const stageRaw = row['Stage'];
  const stageEmpty = stageRaw === undefined || stageRaw === null || stageRaw.toString().trim() === '';
  const stage = stageEmpty ? 1 : Number(stageRaw);

  const isSent = status === 'sent';
  const isDueToday = nextActionDate === todayStr;
  const hasEmail = email.length > 0;
  const isStageOne = stage === 1;

  if (isSent && isDueToday && hasEmail && isStageOne) {
    const city = row['City'] || '';
    output.push({
      json: {
        row_number: row.row_number,
        email,
        firm: row['Firm'] || '',
        contactName: row['Contact Name'] || '',
        city,
        subject: `Re: New companies in ${city} — before they've found an accountant`,
        body: `Hi,\n\nJust checking this landed — inboxes get busy.\n\nIf you would like the ${city} list for this week, reply and I will send it over.\n\nAaron Akoto\naaron.akoto.systems@gmail.com`,
        newNextActionDate: nextActionDateStr
      }
    });
  } else {
    console.log(
      `Skipped row ${row.row_number} (${row['Firm'] || 'unknown firm'}, ${email || 'no email'}): ` +
      `status="${row['Status']}" nextActionDate="${nextActionDate}" stage="${stageRaw}"`
    );
  }
}

return output;
